import { Command } from 'commander';
import { dockerfilesListCommand } from './list.ts';
import { dockerfilesGetCommand } from './get.ts';

export function makeDockerfilesCommands(): Command {
  const cmd = new Command('dockerfiles').description(
    'View the Dockerfiles builds used, generated by Ingot or from the repository',
  );
  cmd.addCommand(dockerfilesListCommand);
  cmd.addCommand(dockerfilesGetCommand);
  return cmd;
}
